        // Create rollback plan
        let plan = RollbackPlan {
            steps: rollback_path.steps,
            state_changes: diff,
            estimated_time: self.estimate_rollback_time(&diff),
        };

        // Execute rollback
        self.execute_rollback_plan(plan).await
    }
