use tch::{nn, Device, Tensor};

pub struct Expert {
    vs: nn::VarStore,
    net: nn::Sequential,
}

impl Expert {
    pub fn new(device: Device) -> Self {
        let vs = nn::VarStore::new(device);
        let net = nn::seq()
            .add(nn::linear(&vs.root() / "l1", 512, 512, Default::default()))
            .add_fn(|xs| xs.relu());
        Expert { vs, net }
    }
    pub fn forward(&self, input: &Tensor) -> Tensor {
        self.net.forward(input)
    }
}
