    fn query_balance(&self, account: &Address) -> Result<Balance, AdapterError>;
    fn subscribe_blocks(&self, handler: impl Fn(Block) + Send + 'static) -> Result<(), AdapterError>;
    // ... more I/O methods as needed
}

