    async fn handle_message(&self, message: ProtocolMessage) -> Result<Option<ProtocolMessage>> {
        match message.message_type {
            MessageType::Ping => {
                // Respond with Pong
                Ok(Some(ProtocolMessage::new(
                    message.sender.clone(),
                    MessageType::Pong
                )))
            },
            _ => Ok(None)
