        let endpoint = self.dht_lookup(addr).await?;

        // 4. Verify resolution proof
        self.verify_resolution_proof(&endpoint, addr)?;

        // 5. Cache result
        self.resolution_cache.insert(*addr, endpoint.clone());

        Ok(endpoint)
    }
