                }
                (rate, time) if rate >= 0.80 && time < self.config.degraded_response_threshold => {
                    HealthStatus::Degraded
                }
                _ => HealthStatus::Unhealthy,
            }
        } else {
            HealthStatus::Unknown
        }
    }
