pub struct ConnectionMultiplexer {
    /// Underlying connection
    connection: Box<dyn NetworkConnection>,

    /// Active streams
    streams: Arc<DashMap<StreamId, MultiplexedStream>>,

    /// Stream allocation
    next_stream_id: AtomicU32,

