    pub fn is_allowed(&self, addr: &SocketAddr) -> bool {
        // Check port
        if !self.allowed_ports.contains(&addr.port()) {
            return false;
        }

        // Check IP blocks
        for blocked in &self.blocked_addresses {
            if blocked.contains(addr.ip()) {
                return false;
            }
        }

        // Check rate limits
        if !self.rate_limits.check_allowed(addr) {
            return false;
        }

        true
    }
