            content: decrypted_data,
            metadata: Some(json!({
                "encrypted": true,
                "vault_id": vault_uri.vault_id
            })),
        })
    }

    fn supports_scheme(&self, scheme: &str) -> bool {
        scheme == "vault"
    }
