export class RefCounted<T> {
    private refCount = 1;

    constructor(
        private value: T,
        private cleanup: () => void
    ) {}

    addRef(): void {
        this.refCount++;
    }

    release(): void {
        if (--this.refCount === 0) {
            this.cleanup();
        }
    }

    get(): T {
        if (this.refCount === 0) {
            throw new Error('Accessing disposed object');
