class CompressionManager {
  private algorithms = {
    zstd: new ZstdCompressor(),      // Best ratio
    lz4: new LZ4Compressor(),        // Fastest
    brotli: new BrotliCompressor(),  // Web optimized
    custom: new CustomCompressor()    // Domain-specific
