class TCPHolePunching {
  async attemptHolePunch(
    remoteEndpoint: Endpoint
  ): Promise<Connection> {
    // 1. Bind to specific local port
    const socket = await this.bindSocket(localPort);

    // 2. Set socket to non-blocking
    socket.setNonBlocking(true);

    // 3. Simultaneous SYN
    const attempts = [];
    for (let i = 0; i < 5; i++) {
