        let array = js_sys::Uint8Array::new_with_length(dest.len() as u32);

        web_sys::window()
            .unwrap()
            .crypto()
            .unwrap()
            .get_random_values_with_u8_array(&array)
            .map_err(|_| RNGError::GenerationFailed)?;

        array.copy_to(dest);
        Ok(())
    }
