        self.last_activity = Instant::now();

        Ok(())
    }

    pub fn get_vault_key(&mut self) -> Result<&[u8], SessionError> {
        self.check_timeout()?;
        self.last_activity = Instant::now();

        self.vault_key
            .as_ref()
            .map(|k| k.as_slice())
            .ok_or(SessionError::NotInitialized)
    }
}
