                VaultChange::UpdateSecret { id, node } => {
                    self.local_vault.write().await
                        .update_node_direct(id, node)?;
                }
                VaultChange::DeleteSecret(id) => {
                    self.local_vault.write().await

               self.local_vault.write().await
                        .add_node_direct(node)?;
