// Transfer tokens
let tx = Transaction::builder()
    .from(&account)
    .to("qd1recipient...")
    .amount(100.0)
    .memo("Payment for resources")
    .build()?;

let result = exchange.submit_transaction(tx).await?;
# Ok(())
# }
