          "memory_threshold_mb": 500
        },
        "rollback_on_failure": true,
        "feature_flags": {
          "dns_cache": true,
          "batch_operations": true,
          "connection_pooling": true,
          "memory_pooling": false,
          "simd_crypto": false
        }
      },
      {
        "name": "expanded_canary",
        "percentage": 50,
        "duration": "1h",
        "metrics": {
          "success_rate_threshold": 99.5,
          "latency_p99_threshold_ms": 150,
          "error_rate_threshold": 0.5,
          "memory_threshold_mb": 600
        },
        "rollback_on_failure": true,
        "feature_flags": {
          "dns_cache": true,
          "batch_operations": true,
          "connection_pooling": true,
          "memory_pooling": true,
          "simd_crypto": false
        }
      },
      {
        "name": "full_rollout",
        "percentage": 100,
        "duration": "24h",
        "metrics": {
          "success_rate_threshold": 99.0,
          "latency_p99_threshold_ms": 200,
          "error_rate_threshold": 1.0,
          "memory_threshold_mb": 700
        },
        "rollback_on_failure": true,
        "feature_flags": {
          "dns_cache": true,
          "batch_operations": true,
          "connection_pooling": true,
          "memory_pooling": true,
          "simd_crypto": true
        }
      }
    ]
  },
  "monitoring": {
    "metrics_interval": "10s",
    "evaluation_window": "5m",
    "alerts": [
      {
        "name": "high_error_rate",
        "condition": "error_rate > 1%",
        "severity": "critical",
        "action": "rollback"
      },
      {
        "name": "high_latency",
        "condition": "p99_latency > 500ms",
        "severity": "warning",
        "action": "notify"
      },
      {
        "name": "memory_leak",
        "condition": "memory_growth > 10% per hour",
        "severity": "critical",
        "action": "rollback"
      }
    ]
  },
  "rollback": {
    "automatic": true,
    "manual_override": true,
    "methods": [
      {
        "priority": 1,
        "method": "feature_flag_disable",
        "timeout": "30s"
      },
      {
        "priority": 2,
        "method": "traffic_routing",
        "timeout": "2m"
      },
      {
        "priority": 3,
        "method": "version_rollback",
        "timeout": "5m"
      }
    ]
  },
  "traffic_routing": {
    "method": "weighted_round_robin",
    "sticky_sessions": false,
    "health_check": {
      "endpoint": "/health",
      "interval": "10s",
      "timeout": "5s",
      "healthy_threshold": 2,
      "unhealthy_threshold": 3
    }
  },
  "feature_flags": {
    "source": "environment",
    "fallback": "config_file",
    "cache_ttl": "60s",
    "defaults": {
      "dns_cache": false,
      "batch_operations": false,
      "connection_pooling": false,
      "memory_pooling": false,
      "simd_crypto": false
    }
  },
  "validation": {
    "pre_deployment": [
      "run_unit_tests",
      "run_integration_tests",
      "run_performance_benchmarks",
      "verify_rollback_capability"
    ],
    "post_deployment": [
      "verify_metrics_collection",
      "verify_feature_flags",
      "verify_traffic_distribution",
      "run_smoke_tests"
    ]
  },
  "notifications": {
    "channels": [
      {
        "type": "slack",
        "webhook": "${SLACK_WEBHOOK_URL}",
        "events": ["deployment_start", "stage_complete", "rollback", "deployment_complete"]
      },
      {
        "type": "email",
        "recipients": ["devops@qudag.io"],
        "events": ["rollback", "deployment_failure"]
      }
    ]
  }
}

